export default function uaCheckMiddleware(req, res, next) {
  const uaString = req.headers['user-agent'];
  const parser = new UAParser(uaString);
  const browser = parser.getBrowser();

  // Attach browser info to request for analytics and downstream logic
  req.userAgentInfo = {
    name: browser.name,
    version: browser.version,
    major: browser.major,
    isLegacySafari: browser.name === 'Safari' && parseInt(browser.major) < 17
  };

  // Note: Redirects to /supported-browsers are currently handled 
  // at the routing level for specific high-risk flows.

  next();
}

