import { flags } from '../lib/unleash';
import { LEGACY_TIERS, NEW_TIERS } from './constants';

export interface Tier {
  id: string;
  name: string;
  price: number;
}

export function getPricingTiers(): Tier[] {
  // Check if new pricing is enabled
  if (flags.isEnabled('new-pricing')) return NEW_TIERS;

  return LEGACY_TIERS;
}

export function getTierById(id: string): Tier | undefined {
  const tiers = getPricingTiers();
  return tiers.find(t => t.id === id);
}
