export async function processCheckout(userId: string, tierId: string) {
  const tiers = getPricingTiers();
  const selectedTier = tiers.find(t => t.id === tierId);

  if (!selectedTier) {
    throw new Error(`Invalid tier: ${tierId}`);
  }

  const user = await db.users.findById(userId);
  const subscription = await stripe.subscriptions.create({
    customer: user.stripeCustomerId,
    items: [{ price: selectedTier.stripePriceId }],
    metadata: {
      tier: selectedTier.name,
      flag_status: unleash.isEnabled('new-pricing') ? 'new' : 'legacy'
    }
  });

  return {
    success: true,
    subscriptionId: subscription.id,
    tier: selectedTier.name
  };
}

export function validateTierSelection(tierId: string): boolean {
  const tiers = getPricingTiers();
  return tiers.some(t => t.id === tierId);
}
