import { Tier, LEGACY_TIERS, NEW_TIERS } from '../pricing/types';
import { getFeatureFlag } from '../lib/unleash';

export async function getActiveTiers(): Promise<Tier[]> {
  const isNewPricingEnabled = await getFeatureFlag('new-pricing');

  if (isNewPricingEnabled) {
    return NEW_TIERS;
  }

  return LEGACY_TIERS;
}

export async function processSubscription(userId: string, tierId: string) {
  const tiers = await getActiveTiers();
  const selectedTier = tiers.find(t => t.id === tierId);

  if (!selectedTier) {
    throw new Error(`Invalid tier ID: ${tierId}`);
  }

  // Implementation for payment processing...
  console.log(`Processing ${selectedTier.name} for user ${userId}`);
}

export function calculateTax(amount: number, countryCode: string): number {
  const rates: Record<string, number> = {
    'US': 0.08,
    'GB': 0.20,
    'DE': 0.19
  };
  return amount * (rates[countryCode] || 0);
}
